import {renderFormula} from './formula.js';
import {RankingClient} from './ranking-client.js';
import {seeded} from './engine.js';
import {Game} from './engine.js';
import {load,record} from './storage.js';
const app=document.querySelector('#app');let difficulty='NORMAL',game=null,screen='title',saved=null;
const rankingClient=new RankingClient(window.HIGHLOW_RANKING_CONFIG||{});let onlineRun=null,onlineMessage='',rankDifficulty='NORMAL',rankPeriod='daily',rankRequest=0;
const head=()=>`<header><span>HIGH<span style="color:var(--gold)">×</span>LOW</span><span class="version"><i class="status"></i>SOLO ARCADE · VER.1.0 · TEST</span></header>`;
function setTheme(value){document.body.dataset.difficulty=value.toLowerCase()}
const fmt=n=>Math.round(n).toLocaleString('ja-JP');
function title(){setTheme(difficulty);screen='title';game=null;app.innerHTML=head()+`<section class="title"><div class="eyebrow title-badge">ひらめき×30秒</div><div class="hero-doodles" aria-hidden="true"><span>＋</span><span>÷</span><span>＝</span><span>√</span></div><h1 class="logo">HIGH<span class="x">×</span><span class="low">LOW</span></h1><p class="tagline">大きいのは、どっち？ 比べて、ひらめけ！</p><div class="demo" aria-hidden="true"><div><small>LEFT</small><span class="formula" id="demo-left"></span></div><span>VS</span><div><small>RIGHT</small><span class="formula" id="demo-right"></span></div></div><div class="section-label">難易度をえらぼう <span>SELECT LEVEL</span></div><div class="difficulties">${['EASY','NORMAL','HARD'].map((d,i)=>`<button class="difficulty ${d===difficulty?'selected':''}" data-difficulty="${d}" aria-pressed="${d===difficulty}"><span class="level-dots" aria-hidden="true">${['●','●●','●●●'][i]}</span><strong>${d}</strong><small>${['四則演算 / 2択','四則演算 / 3択','高校数学 / 3択'][i]}</small></button>`).join('')}</div><p class="best">PERSONAL BEST <b>${fmt(load().records[difficulty]?.best||0)}</b></p><div class="title-actions"><button class="primary" id="play">PLAY <span>↗</span></button><button class="secondary" id="ranking">RANKING</button></div><p class="hint">← 左が大きい　 ↓ 同じ　 → 右が大きい${difficulty==='EASY'?'（↓は使用しません）':''}</p><details><summary>遊び方・ルール <span>HOW TO PLAY</span></summary><p>左右の式を比べて、大きい方をタップ。同じ値なら EQUAL。EASYは左右の2択です。<br>考える時間は30秒。正解で100点、5連続で120点、10連続で150点、20連続で200点。誤答は−100点でコンボが0に戻ります。<br>正誤表示の0.3秒は制限時間に含みません。別タブや別アプリに移動すると中断し、記録は保存されません。三角関数の角度は度数法（°）です。</p></details></section><footer>THINK FAST. AIM HIGH.</footer>`;renderFormula(document.querySelector('#demo-left'),'8 × 7');renderFormula(document.querySelector('#demo-right'),'63 − 9');app.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.difficulty;title()});document.querySelector('#play').onclick=start;document.querySelector('#ranking').onclick=()=>showRanking()}
async function start(){if(screen==='connecting')return;setTheme(difficulty);saved=null;onlineRun=null;onlineMessage='';screen='connecting';app.innerHTML=head()+'<section class="results"><p role="status">試合を準備しています…</p></section>';try{onlineRun=await rankingClient.start(difficulty)}catch(e){onlineMessage=e.message+' 今回はランキング対象外です。'}if(document.hidden){onlineRun=null;title();return}screen='game';game=new Game(difficulty,onlineRun?{rng:seeded(onlineRun.seed)}:{});game.start();app.innerHTML=head()+`<section class="game"><div class="game-top"><span class="pill">${difficulty} / SOLO</span><button class="quiet" id="exit">中断する ×</button></div><div class="stats"><div><small>TIME LEFT</small><strong id="time">30.0</strong></div><div><small>SCORE</small><strong class="gold" id="score">0</strong></div><div><small>COMBO</small><strong id="combo">0</strong></div></div><div class="timer-bar"><i id="bar"></i></div><p class="online-mode" id="online-mode"></p><p class="prompt">大きい方を選べ${difficulty==='EASY'?'':'。同じなら EQUAL'}</p><div class="arena"><button class="card" id="left" aria-label="LEFT 左が大きい"><span class="side">LEFT</span><span class="formula" id="lf"></span><kbd>←</kbd></button><span class="versus">VS</span><button class="card right" id="right" aria-label="RIGHT 右が大きい"><span class="side">RIGHT</span><span class="formula" id="rf"></span><kbd>→</kbd></button></div>${difficulty==='EASY'?'':'<button class="equal" id="equal"><span>＝</span>EQUAL <small>↓</small></button>'}<div class="feedback" id="feedback" role="status"></div><footer>TRUST YOUR NUMBERS.</footer></section><div class="countdown" id="countdown"><span>GET READY</span><b>3</b><span>大きい数式をタップ</span></div>`;['LEFT','RIGHT','EQUAL'].forEach(c=>{const b=document.getElementById(c.toLowerCase());if(b)b.onclick=()=>answer(c)});document.querySelector('#exit').onclick=()=>{game.interrupt();results()};document.querySelector('#online-mode').textContent=onlineRun?'オンライン記録対象':onlineMessage;render()}
function answer(c){if(game&&screen==='game'){game.answer(c);render()}}
function render(){if(screen!=='game')return;if(game.state==='FINISHED'){results();return}const countdown=document.querySelector('#countdown');if(game.state==='COUNTDOWN'){countdown.querySelector('b').textContent=Math.max(1,Math.ceil((game.until-performance.now())/1000))}else countdown.hidden=true;countdown.style.display=game.state==='COUNTDOWN'?'flex':'none';const left=game.timeLeft();document.querySelector('#time').textContent=(left/1000).toFixed(1);document.querySelector('#bar').style.width=left/300+'%';document.querySelector('#score').textContent=fmt(game.score);document.querySelector('#combo').textContent=game.combo;['LEFT','RIGHT','EQUAL'].forEach(c=>{let b=document.getElementById(c.toLowerCase());if(b)b.disabled=game.state!=='PLAYING'});if(game.question){renderFormula(document.querySelector('#lf'),game.question.leftExpression);renderFormula(document.querySelector('#rf'),game.question.rightExpression)}let f=document.querySelector('#feedback'),feedback=game.state==='FEEDBACK';f.className='feedback '+(feedback?(game.isCorrect?'good':'bad'):'');f.textContent=feedback?(game.isCorrect?`✓ CORRECT　+${game.delta}`:`✕ MISS　−100　 正解：${game.question.answer==='EQUAL'?'LEFT ＝ RIGHT':game.question.answer==='LEFT'?'LEFT ＞ RIGHT':'LEFT ＜ RIGHT'}`):'';document.querySelector('.game').className='game '+(feedback?(game.isCorrect?'flash-good':'flash-bad'):'')}
function results(){screen='results';const s=game.stats();saved=game.interrupted?{saved:false,isBest:false}:record(difficulty,game);app.innerHTML=head()+`<section class="results"><span class="eyebrow">${difficulty} / SOLO RESULT</span><h1>${game.interrupted?'SESSION INTERRUPTED':'TIME UP. WELL PLAYED.'}</h1>${game.interrupted?'<p class="interrupted">プレイを中断しました。記録は保存されません。</p>':''}<div class="final-score">${fmt(s.score)}</div><div class="eyebrow">TOTAL SCORE</div><div class="record">${saved.isBest?'★ NEW PERSONAL BEST':'次の30秒で、自分を超えよう。'}</div><div class="result-grid">${[['CORRECT / 正解',s.correct],['MISS / 誤答',s.wrong],['ACCURACY / 正答率',s.accuracy.toFixed(1)+'%'],['MAX COMBO',s.maxCombo],['AVG TIME / 平均', (s.average/1000).toFixed(2)+'s'],['DIFFICULTY',difficulty]].map(([l,v])=>`<div><small>${l}</small><b>${v}</b></div>`).join('')}</div>${!saved.saved&&!game.interrupted?'<p class="save-note">保存できませんでした。ブラウザの保存設定をご確認ください。</p>':''}<div class="online-result" id="online-result" role="status"></div><button class="secondary" id="result-ranking">RANKING</button><button class="primary" id="retry">RETRY ↻</button><button class="secondary" id="title">TITLE</button></section>`;document.querySelector('#retry').onclick=start;document.querySelector('#title').onclick=title;document.querySelector('#result-ranking').onclick=()=>showRanking();if(!game.interrupted&&onlineRun)syncResult(game,onlineRun);else document.querySelector('#online-result').textContent=game.interrupted?'ランキングには登録されません。':onlineMessage}
document.addEventListener('keydown',e=>{if(screen!=='game'||e.repeat)return;const c={ArrowLeft:'LEFT',ArrowRight:'RIGHT',ArrowDown:'EQUAL'}[e.key];if(c){e.preventDefault();answer(c)}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&screen==='game'){game.interrupt();results()}});window.addEventListener('pagehide',()=>{if(game&&screen==='game')game.interrupt()});function loop(){if(game&&screen==='game'){game.tick();render()}requestAnimationFrame(loop)}title();requestAnimationFrame(loop);
async function syncResult(completedGame,run){const target=document.querySelector('#online-result');if(!target)return;target.textContent='ランキングに記録を送信しています…';try{const response=await rankingClient.submit(run.runId,completedGame);if(screen!=='results'||game!==completedGame)return;target.textContent=response.registered?'✓ 記録を登録しました。各期間の最高記録を確認し、更新分を反映しました。':'✓ 記録を保存しました。RANKINGでニックネームを登録すると掲載されます。'}catch(e){if(screen!=='results'||game!==completedGame)return;target.textContent=e.message+' ';const button=document.createElement('button');button.className='quiet';button.textContent='再送信';button.onclick=()=>syncResult(completedGame,run);target.append(button)}}
async function showRanking(){setTheme(rankDifficulty);screen='ranking';const current=++rankRequest;app.innerHTML=head()+`<section class="rankings"><div class="game-top"><h1>RANKING</h1><button class="quiet" id="rank-title">TITLE</button></div><p class="ranking-note">日本時間で集計・週間は月曜0時から。得点 → 正答率 → 平均回答時間の順。完全同点は同順位です。</p><form id="nickname-form"><label for="nickname">ニックネーム（1〜16文字）</label><div class="name-input"><input id="nickname" name="nickname" maxlength="32" autocomplete="nickname" placeholder="ニックネームを登録"><button class="secondary" type="submit">登録</button></div><p id="name-status" role="status"></p></form><div class="rank-filters"><label>難易度<select id="rank-difficulty">${['EASY','NORMAL','HARD'].map(d=>`<option ${d===rankDifficulty?'selected':''}>${d}</option>`).join('')}</select></label><label>集計期間<select id="rank-period">${[['daily','デイリー'],['weekly','週間'],['all','歴代']].map(([v,l])=>`<option value="${v}" ${v===rankPeriod?'selected':''}>${l}</option>`).join('')}</select></label></div><div id="rank-me" class="my-rank"></div><p id="rank-period-label" class="ranking-note"></p><div id="rank-status" role="status">ランキングを読み込んでいます…</div><div class="ranking-table-wrap"><table class="ranking-table"><thead><tr><th scope="col">順位</th><th scope="col">プレイヤー</th><th scope="col">得点</th><th scope="col">正答率</th><th scope="col">平均</th></tr></thead><tbody id="rank-rows"></tbody></table></div><button class="secondary" id="rank-refresh">更新</button><p class="ranking-note">このブラウザの識別情報を使用します。保存情報を削除すると別プレイヤーになります。</p></section>`;document.querySelector('#rank-title').onclick=title;document.querySelector('#rank-difficulty').onchange=e=>{rankDifficulty=e.target.value;showRanking()};document.querySelector('#rank-period').onchange=e=>{rankPeriod=e.target.value;showRanking()};document.querySelector('#rank-refresh').onclick=()=>showRanking();const nameInput=document.querySelector('#nickname');nameInput.value=rankingClient.profile?.player.nickname||'';document.querySelector('#nickname-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const status=document.querySelector('#name-status');try{await rankingClient.identity();await rankingClient.nickname(nameInput.value);if(screen==='ranking'&&current===rankRequest)await showRanking()}catch(error){if(screen==='ranking'&&current===rankRequest)status.textContent=error.message}finally{button.disabled=false}};
 try{const data=await rankingClient.ranking(rankDifficulty,rankPeriod);if(screen!=='ranking'||current!==rankRequest)return;nameInput.value=rankingClient.profile?.player.nickname||'';document.querySelector('#rank-status').textContent=data.rows.length?'上位100名を表示しています。':'まだ記録がありません。最初の記録を残そう。';document.querySelector('#rank-period-label').textContent=data.period==='all'?'歴代の最高記録':(data.period==='weekly'?'週の開始日：':'対象日：')+data.periodKey+'（日本時間）';document.querySelector('#rank-me').textContent=data.me?`あなた：${data.me.rank}位 / ${data.totalPlayers}名　最高 ${fmt(data.me.score)}点`:'あなた：この期間の掲載記録はまだありません。ニックネーム登録と試合完走で掲載されます。';const tbody=document.querySelector('#rank-rows');for(const row of data.rows){const tr=document.createElement('tr');if(row.isMe)tr.className='is-me';for(const text of [String(row.rank),row.nickname,fmt(row.score),row.accuracy.toFixed(1)+'%',row.averageMs===null?'—':(row.averageMs/1000).toFixed(2)+'s']){const td=document.createElement('td');td.textContent=text;tr.append(td)}tbody.append(tr)}}catch(e){if(screen==='ranking'&&current===rankRequest)document.querySelector('#rank-status').textContent=e.message}}
